"""Text and JSON renderings shared by the book commands and the book-less ``calc`` commands."""

from datetime import date

from tallybook.dates import Period, last_day
from tallybook.errors import ValidationError
from tallybook.export import render_table, to_json, transactions_to_json
from tallybook import reports

REPORT_KINDS = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")


def tx_table(txs):
    """The ``tx list`` table; the empty string for no transactions."""
    rows = [
        [tx.id, tx.date.isoformat(), tx.flag, tx.payee, tx.narration, " ".join("#" + t for t in sorted(set(tx.tags)))]
        for tx in txs
    ]
    if not rows:
        return ""
    return render_table(["Id", "Date", "Flag", "Payee", "Narration", "Tags"], rows, "rlllll")


def transactions_json(txs):
    """The JSON list of transaction objects."""
    return transactions_to_json(list(txs))


def _money(m):
    return "%s %s" % (m.amount_str(), m.currency)


def budget_table(lines):
    """The ``budget status`` table; the empty string for no lines."""
    rows = [
        [
            ln.pattern,
            ln.period_kind,
            _money(ln.budget),
            _money(ln.actual),
            _money(ln.remaining),
            "%s%%" % ln.percent,
            "over" if ln.over else "",
        ]
        for ln in lines
    ]
    if not rows:
        return ""
    return render_table(["Pattern", "Per", "Budget", "Actual", "Remaining", "Percent", "Over"], rows, "llrrrrl")


def budget_lines_json(lines):
    """The JSON list of ``BudgetLine.to_dict()`` objects."""
    return to_json([ln.to_dict() for ln in lines])


def month_of(today):
    """The calendar month containing ``today`` as a Period."""
    return Period(date(today.year, today.month, 1), date(today.year, today.month, last_day(today.year, today.month)))


def run_report(kind, ledger, *, account=None, as_of=None, period=None, convert=None, rollup=False, today, as_json=False):
    """Run one report with the command line defaults and return its text (or JSON document)."""
    if kind == "trial-balance":
        report = reports.trial_balance(ledger, as_of)
    elif kind == "balance-sheet":
        report = reports.balance_sheet(ledger, as_of if as_of is not None else today, convert_to=convert, today=today)
    elif kind == "income-statement":
        report = reports.income_statement(ledger, period if period is not None else month_of(today), convert_to=convert)
    elif kind == "cashflow":
        report = reports.cashflow(ledger, period if period is not None else month_of(today))
    elif kind == "register":
        if account is None:
            raise ValidationError("register needs an account")
        report = reports.register(ledger, account, period, rollup=bool(rollup))
    else:
        raise ValidationError("unknown report: %s" % kind)
    return to_json(report) if as_json else reports.render_text(report)
